from pysat.solvers import Glucose3
from pysat.card import CardEnc

n = 22

# Fixed assignments: q[row] = col
fixed = {11: 8, 16: 14, 18: 11, 21: 13}

# We'll create variables: var[row][col] = True means queen at (row, col)
# Use 1-indexed for pysat
def var_id(row, col):
    return row * n + col + 1

solver = Glucose3()

# Each row has exactly one queen
for r in range(n):
    lits = [var_id(r, c) for c in range(n)]
    solver.add_clause(lits)  # at least one
    # at most one
    for i in range(n):
        for j in range(i+1, n):
            solver.add_clause([-var_id(r, i), -var_id(r, j)])

# Each column has at most one queen
for c in range(n):
    for r1 in range(n):
        for r2 in range(r1+1, n):
            solver.add_clause([-var_id(r1, c), -var_id(r2, c)])

# Diagonals (top-left to bottom-right): r-c constant
from collections import defaultdict
diag1 = defaultdict(list)
for r in range(n):
    for c in range(n):
        diag1[r-c].append(var_id(r, c))
for d in diag1.values():
    for i in range(len(d)):
        for j in range(i+1, len(d)):
            solver.add_clause([-d[i], -d[j]])

# Diagonals (top-right to bottom-left): r+c constant
diag2 = defaultdict(list)
for r in range(n):
    for c in range(n):
        diag2[r+c].append(var_id(r, c))
for d in diag2.values():
    for i in range(len(d)):
        for j in range(i+1, len(d)):
            solver.add_clause([-d[i], -d[j]])

# Fixed assignments
for r, c in fixed.items():
    solver.add_clause([var_id(r, c)])

result = solver.solve()
print("SAT" if result else "UNSAT")

if result:
    model = solver.get_model()
    solution = [None] * n
    for r in range(n):
        for c in range(n):
            if model[var_id(r, c)-1] > 0:
                solution[r] = c
    print(solution)
